<?php
declare(strict_types=1);namespace App\Services;use App\Repositories\{AuditRepository,RtmpRepository};use App\Security\{Auth,DeviceCredentialCipher};use PDO;use RuntimeException;
final readonly class RtmpService{public function __construct(private PDO $db,private RtmpRepository $repo,private AuditRepository $audit,private DeviceCredentialCipher $cipher){}
 public function save(array $in):int{$server=(int)($in['server_id']??0);$port=(int)($in['port']??1935);if($server<1||$port<1024||$port>65535)throw new RuntimeException('Balanceador o puerto RTMP inválido.');$ips=[];foreach(preg_split('/[\s,;]+/',(string)($in['allowed_ips']??''),-1,PREG_SPLIT_NO_EMPTY) as $ip){if(!filter_var($ip,FILTER_VALIDATE_IP)||in_array($ip,['0.0.0.0','::'],true))throw new RuntimeException('IP de ingest inválida: '.$ip);$ips[$ip]=true;}if(isset($in['enabled'])&&!$ips)throw new RuntimeException('RTMP habilitado requiere al menos una IP de ingest autorizada.');$exists=$this->db->prepare('SELECT id,publish_key_ciphertext,desired_version FROM rtmp_ingest_configs WHERE server_id=?');$exists->execute([$server]);$old=$exists->fetch();$key=$old?$old['publish_key_ciphertext']:$this->cipher->encrypt(bin2hex(random_bytes(24)));$application=$old?null:'ingest_'.bin2hex(random_bytes(8));$this->db->beginTransaction();try{if($old){$this->db->prepare("UPDATE rtmp_ingest_configs SET enabled=?,port=?,desired_version=desired_version+1,status='pending',last_error=NULL,updated_by=? WHERE id=?")->execute([isset($in['enabled']),$port,Auth::id(),$old['id']]);$id=(int)$old['id'];}else{$this->db->prepare("INSERT INTO rtmp_ingest_configs(server_id,enabled,port,application_name,publish_key_ciphertext,status,updated_by) VALUES(?,?,?,?,?,'pending',?)")->execute([$server,isset($in['enabled']),$port,$application,$key,Auth::id()]);$id=(int)$this->db->lastInsertId();}$this->db->prepare('DELETE FROM rtmp_ingest_ips WHERE config_id=?')->execute([$id]);$s=$this->db->prepare('INSERT INTO rtmp_ingest_ips(config_id,ip) VALUES(?,?)');foreach(array_keys($ips) as $ip)$s->execute([$id,$ip]);$this->db->commit();$this->audit->record('rtmp.configuration_saved','rtmp_ingest_config',$id,['server_id'=>$server,'enabled'=>isset($in['enabled']),'port'=>$port,'allowed_ips'=>array_keys($ips)]);return $id;}catch(\Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}}
 public function rotate(int $id):void{$c=$this->repo->find($id)??throw new RuntimeException('Configuración RTMP no encontrada.');$this->db->prepare("UPDATE rtmp_ingest_configs SET publish_key_ciphertext=?,desired_version=desired_version+1,status='pending',last_error=NULL,updated_by=? WHERE id=?")->execute([$this->cipher->encrypt(bin2hex(random_bytes(24))),Auth::id(),$id]);$this->audit->record('rtmp.publish_key_rotated','rtmp_ingest_config',$id,['server_id'=>$c['server_id']]);}
 public function reveal(int $id):array{$c=$this->repo->find($id)??throw new RuntimeException('Configuración RTMP no encontrada.');$this->audit->record('rtmp.publish_key_revealed','rtmp_ingest_config',$id,['server_id'=>$c['server_id']]);$host=$c['public_ip']?:$c['private_ip'];$secret=$this->cipher->decrypt($c['publish_key_ciphertext']);return ['url'=>'rtmp://'.$host.':'.$c['port'].'/'.$c['application_name'].'_'.$secret,'stream_key'=>'live'];}
}
